/**
 * The engine, exposed to a model as AI SDK tools.
 *
 * The same names the pi extension uses -- `portents_roll`, `portents_oracle` and so
 * on -- because `@portents/guidance` names them in prose, and that prose is shared
 * between the two harnesses. A demo that called them something else would need its own
 * copy of the guidance, which is the duplication this project keeps designing away.
 *
 * Schemas are declared with the SDK's `jsonSchema` helper rather than Zod, to avoid
 * pulling a validation library into a bundle that ships to a browser.
 */

import { executeCommand, PROTOCOL_VERSION } from "@portents/web";
import type { Command, CommandResult, WebSession } from "@portents/web";
import { jsonSchema, type Tool, tool } from "ai";

import {
	campaignAction,
	type CampaignParams,
	recallAction,
	type RecallParams,
	rememberAction,
	type RememberParams,
	sheetAction,
	type SheetParams,
} from "./actions.ts";

async function dispatch(session: WebSession, command: Command): Promise<CommandResult> {
	return executeCommand(session, { version: PROTOCOL_VERSION, command });
}

function commandText(result: CommandResult): string {
	if (result.type !== "text") throw new Error(`Expected text command result, received ${result.type}`);
	return result.text;
}

/** What a tool call did, for the transcript and the GM pane. */
export interface ToolTrace {
	readonly name: string;
	readonly summary: string;
	/**
	 * The full result, including anything the transcript hides.
	 *
	 * Carried so the GM pane and the ledger can offer to reveal it. Solo play needs the
	 * mechanism hidden *by default*, not permanently: the player is also the person
	 * checking that the dice were real, and refusing to ever show them makes the
	 * accountability claim unfalsifiable.
	 */
	readonly detail?: string;
	/**
	 * May the player see this?
	 *
	 * The secrecy rule the whole project is built around: dice the player's character
	 * rolls are public and cited, world-generation randomness is not. The transcript UI
	 * hides the private ones, so an oracle answer does not leak through the very
	 * interface meant to conceal it.
	 */
	readonly secret: boolean;
}

const str = (description: string) => ({ type: "string" as const, description });

/**
 * Prefix a GM-facing result with the rule it is about to tempt the model to break.
 *
 * These results carry the mechanism -- an oracle answer arrives as
 * "**NO, AND** ... _unlikely, d100 91 vs 30_" -- and a model that pastes that into its
 * reply has told the player which parts of the world were dice and which were
 * authored. The transcript already hides the tool call; this stops the *text* leaking
 * through the reply instead. The pi extension does the same thing for the same reason.
 */
const gmOnly = (body: string) =>
	[
		"[GM-FACING — the player must not see this]",
		"Translate it into fiction. Do not quote it, name a tool, cite an id, or mention dice.",
		"",
		body,
	].join("\n");
const num = (description: string) => ({ type: "number" as const, description });

/**
 * Build the tool set for one session.
 *
 * `onTrace` is how the UI learns what happened; the model's own view is the returned
 * string. Both matter: the model needs the result, the player needs to see that a real
 * die was rolled.
 */
export function portentsTools(session: WebSession, onTrace: (trace: ToolTrace) => void): Record<string, Tool> {
	const trace = (name: string, summary: string, secret = false, detail?: string) =>
		onTrace({ name, summary, secret, ...(detail ? { detail } : {}) });

	return {
		portents_roll: tool({
			description:
				"Roll dice for anything the GM rolls: monster attacks, damage, NPC saves, hidden checks. " +
				"Foundry notation: 2d20kh1 (advantage), 4d6kh3, 1d8+3, 8d6, 6#4d6kh3 to repeat. " +
				"Never write a die result you did not get from this tool.",
			inputSchema: jsonSchema<{ expression: string; reason?: string; dc?: number }>({
				type: "object",
				properties: {
					expression: str('Dice expression, e.g. "2d20kh1+5"'),
					reason: str("What the roll is for"),
					dc: num("Target number, if there is one"),
				},
				required: ["expression"],
			}),
			execute: async ({ expression, reason, dc }) => {
				const result = await dispatch(session, {
					type: "dice.roll",
					expression,
					...(reason === undefined ? {} : { reason }),
					...(dc === undefined ? {} : { dc }),
					...(session.campaign ? { campaignId: session.campaign.slug } : {}),
				});
				if (result.type !== "roll") throw new Error("Roll command returned an unexpected result");
				trace("roll", `${expression} → ${result.totals.join(", ")}`, false, result.lines.join("\n"));
				return result.lines.join("\n");
			},
		}),

		portents_ask_roll: tool({
			description:
				"Ask the PLAYER to roll their own dice: their attacks, damage, checks, saves, initiative, " +
				"death saves, hit dice. Use this rather than rolling for them. Returns their result.",
			inputSchema: jsonSchema<{ expression: string; reason: string; dc?: number }>({
				type: "object",
				properties: {
					expression: str('What they should roll, e.g. "1d20+5"'),
					reason: str('What it is for, e.g. "Stealth past the sentry"'),
					dc: num("The DC, if they may know it"),
				},
				required: ["expression", "reason"],
			}),
			// Resolved by the UI, not here: it has to wait for a human. See askRoll in main.ts.
			execute: undefined as never,
		}),

		portents_odds: tool({
			description: "Probability of a dice expression: mean, spread, and the chance of meeting a DC.",
			inputSchema: jsonSchema<{ expression: string; dc?: number }>({
				type: "object",
				properties: { expression: str("Dice expression"), dc: num("Report the chance of at least this") },
				required: ["expression"],
			}),
			execute: async ({ expression, dc }) => commandText(await dispatch(session, {
				type: "dice.odds",
				expression,
				...(dc === undefined ? {} : { dc }),
			})),
		}),

		portents_oracle: tool({
			description:
				"Answer a question about the world you have NOT already decided, using dice instead of your " +
				'own judgement. Kinds: yes_no (with a likelihood), meaning, how_many, reaction, scene, gm_move. ' +
				"GM-FACING: translate the answer into fiction. Never tell the player you consulted it.",
			inputSchema: jsonSchema<{ kind: string; question?: string; likelihood?: string }>({
				type: "object",
				properties: {
					kind: {
						type: "string",
						enum: ["yes_no", "meaning", "how_many", "reaction", "scene", "gm_move"],
						description: "What sort of answer you need",
					},
					question: str("The question, for yes_no"),
					likelihood: {
						type: "string",
						enum: ["certain", "very likely", "likely", "even", "unlikely", "very unlikely", "impossible"],
						description: "How likely a yes is. Defaults to even.",
					},
				},
				required: ["kind"],
			}),
			execute: async ({ kind, question, likelihood }) => {
				const answer = commandText(await dispatch(session, {
					type: "oracle.answer",
					kind,
					...(question === undefined ? {} : { question }),
					...(likelihood === undefined ? {} : { likelihood }),
					...(session.campaign ? { campaignId: session.campaign.slug } : {}),
				}));
				trace("oracle", `${kind}${question ? `: ${question}` : ""}`, true, answer);
				return gmOnly(answer);
			},
		}),

		portents_table: tool({
			description:
				"Roll on a random content table: encounters, weather, rumours, names, hooks, dressing, traps, " +
				"treasure, NPC mannerisms. GM-FACING: use the result, do not quote the table or say you rolled.",
			inputSchema: jsonSchema<{ table: string }>({
				type: "object",
				properties: { table: str('Table id, e.g. "encounters-dungeon". Omit to list.') },
				required: [],
			}),
			execute: async ({ table }) => {
				if (!table) {
					const listed = await dispatch(session, { type: "table.list" });
					if (listed.type !== "catalog") throw new Error("Table list returned an unexpected result");
					return `Tables: ${listed.ids.join(", ")}`;
				}
				const result = commandText(await dispatch(session, {
					type: "table.roll",
					tableId: table,
					...(session.campaign ? { campaignId: session.campaign.slug } : {}),
				}));
				trace("table", table, true, result);
				return gmOnly(result);
			},
		}),

		portents_deck: tool({
			description:
				"Draw from a content deck. With a campaign open the pile persists, so a drawn card stays gone. " +
				"GM-FACING except crit/fumble cards resolving the player's own attack, which they watched happen.",
			inputSchema: jsonSchema<{ deck: string; count?: number }>({
				type: "object",
				properties: { deck: str('Deck id, e.g. "crit-hits". Omit to list.'), count: num("How many (default 1)") },
				required: [],
			}),
			execute: async ({ deck, count }) => {
				if (!deck) {
					const listed = await dispatch(session, { type: "deck.list" });
					if (listed.type !== "catalog") throw new Error("Deck list returned an unexpected result");
					return `Decks: ${listed.ids.join(", ")}`;
				}
				const result = commandText(await dispatch(session, {
					type: "deck.draw",
					deckId: deck,
					count: count ?? 1,
					...(session.campaign ? { campaignId: session.campaign.slug } : {}),
				}));
				trace("deck", `${deck} ×${count ?? 1}`, deck.startsWith("crit-") ? false : true, result);
				return deck.startsWith("crit-") ? result : gmOnly(result);
			},
		}),

		portents_map: tool({
			description:
				"Generate a dungeon. Returns a text grid to show the player, and draws the vector map beside " +
				"the chat. Seeded, so the same seed regenerates the same map.",
			inputSchema: jsonSchema<{ rooms?: number; seed?: string }>({
				type: "object",
				properties: { rooms: num("Target room count (default 9)"), seed: str("Reuse to regenerate exactly") },
				required: [],
			}),
			execute: async ({ rooms, seed }) => {
				const result = await dispatch(session, { type: "map.generate", rooms: rooms ?? 9, ...(seed === undefined ? {} : { seed }) });
				if (result.type !== "map") throw new Error("Map command returned an unexpected result");
				trace("map", `${rooms ?? 9} rooms, seed ${result.seed}`, false, result.ascii);
				return result.ascii;
			},
		}),

		portents_campaign: tool({
			description:
				"Create, open and update the campaign. Actions: list, create, open/load, brief, journal, scene, clock, world, setting, system. " +
				"State persists in this browser. Write to the journal at the end of every scene; read or append legacy world.md with world.",
			inputSchema: jsonSchema<{
				action: string;
				name?: string;
				system?: string;
				premise?: string;
				tone?: string;
				safety?: string;
				setting?: string;
				heading?: string;
				body?: string;
				summary?: string;
				location?: string;
				time?: string;
				tension?: string;
				section?: string;
				clock_name?: string;
				filled?: number;
				segments?: number;
			}>({
				type: "object",
				properties: {
					action: {
						type: "string",
						enum: ["list", "create", "open", "load", "brief", "journal", "scene", "clock", "world", "setting", "system"],
						description: "What to do",
					},
					name: str("Campaign name (create) or slug (open)"),
					system: str('System line, e.g. "5e (2024)"'),
					premise: str("Campaign premise"),
					tone: str("Desired tone"),
					safety: str("Lines, veils, and table agreements"),
					setting: str("Predefined setting id; omit for homebrew"),
					heading: str("Journal entry heading"),
					body: str("Journal or world text"),
					summary: str("Scene summary"),
					location: str("Where the party is"),
					time: str("When the scene is happening"),
					tension: str("Scene mood or combat state"),
					section: { type: "string", enum: ["NPCs", "Places", "Threads", "Factions"], description: "Legacy world.md section" },
					clock_name: str("Clock name"),
					filled: num("Segments filled"),
					segments: num("Segments total"),
				},
				required: ["action"],
			}),
			execute: async (params: CampaignParams) => campaignAction(session, params),
		}),

		portents_sheet: tool({
			description:
				"Read and write character sheets. Actions: create, read, patch_status, set_section, append_section, list, set_main. " +
				"Patch a sheet the moment anything changes: damage, healing, a spent slot, an item. " +
				"**Every character needs a sheet, sidekicks included** — the first one created becomes the " +
				"main character and later ones are sidekicks, so create the player's character first. " +
				'Pass main: true only to deliberately change who the main character is.',
			inputSchema: jsonSchema<{
				action: string;
				character?: string;
				main?: boolean;
				concept?: string;
				section?: string;
				body?: string;
				status?: Record<string, string>;
				abilities?: Record<string, string>;
			}>({
				type: "object",
				properties: {
					action: {
						type: "string",
						enum: ["create", "read", "patch_status", "set_section", "append_section", "list", "set_main"],
						description: "What to do",
					},
					character: str("Character name"),
					main: {
						type: "boolean",
						description:
							"Make this the main character. Omit when creating a sidekick: the first character created is the main one automatically.",
					},
					concept: str('e.g. "Level 3 Wood Elf Ranger"'),
					section: str("Section heading"),
					body: str("Markdown for the section"),
					status: {
						type: "object",
						additionalProperties: { type: "string" },
						description: 'Status keys, e.g. {"HP": "-7"}. Deltas allowed.',
					},
					abilities: {
						type: "object",
						additionalProperties: { type: "string" },
						description: 'e.g. {"STR": "12 (+1)"}',
					},
				},
				required: ["action"],
			}),
			execute: async (params: SheetParams) => sheetAction(session, params),
		}),

		portents_recall: tool({
			description:
				"Search or read predefined-setting and campaign Markdown resources. Before describing a named place, NPC, faction, thread, or recurring ruling, query it here rather than reconstructing it from chat. Pass id for an exact read.",
			inputSchema: jsonSchema<RecallParams>({
				type: "object",
				properties: {
					id: str("Exact stable resource id to read"),
					query: str("Words, name, or alias to find"),
					kind: str("Optional folder kind such as npc, place, faction, or thread"),
					limit: num("Maximum matches, 1 to 100"),
				},
				required: [],
			}),
			execute: async (params) => {
				const result = await recallAction(session, params);
				trace("recall", params.id ?? params.query ?? "list", true, result);
				return gmOnly(result);
			},
		}),

		portents_remember: tool({
			description:
				"Create or replace one campaign Markdown resource under world/<kind>/<slug>.md. Use when a named NPC, place, faction, thread, ruling, or other reusable fact becomes canon. Read before replacing an existing path. Packaged setting resources are immutable.",
			inputSchema: jsonSchema<RememberParams>({
				type: "object",
				properties: {
					path: str('Existing path or explicit destination, e.g. "npc/nesta.md"'),
					id: str("Stable campaign resource id; generated on first write when omitted"),
					kind: str("Lowercase resource kind, e.g. npc, place, faction, thread, ruling"),
					name: str("Display name"),
					body: str("Arbitrary Markdown body"),
					aliases: { type: "array", items: { type: "string" } },
					tags: { type: "array", items: { type: "string" } },
					links: { type: "array", items: { type: "string" } },
					audience: { type: "array", items: { type: "string" }, description: '"gm", "all", or "participant/<id>"' },
					supersedes: str("Packaged resource id this campaign development updates"),
					metadata: { type: "object", additionalProperties: true },
				},
				required: [],
			}),
			execute: async (params) => {
				const result = await rememberAction(session, params);
				trace("remember", params.path ?? params.name ?? "resource", true, result);
				return gmOnly(result);
			},
		}),

		portents_guidance: tool({
			description:
				"Read deeper GM guidance on one topic: character-creation, combat, solo-techniques. " +
				"The standing guidance is already in your context; read a topic when it is about to matter.",
			inputSchema: jsonSchema<{ topic: string }>({
				type: "object",
				properties: {
					topic: {
						type: "string",
						enum: ["character-creation", "combat", "solo-techniques"],
						description: "Which topic",
					},
				},
				required: ["topic"],
			}),
			execute: async ({ topic }) => commandText(await dispatch(session, { type: "guidance.get", topic })),
		}),

		portents_verify_roll: tool({
			description: "Look up a ledger id to confirm a roll really happened and what it produced.",
			inputSchema: jsonSchema<{ id: string }>({
				type: "object",
				properties: { id: str('Ledger id, e.g. "r-12"') },
				required: ["id"],
			}),
			execute: async ({ id }) => session.campaign
				? commandText(await dispatch(session, { type: "ledger.verify", campaignId: session.campaign.slug, id }))
				: session.verify(id),
		}),
	};
}

/** Tool names whose results the player may see. Everything else is GM-facing. */
export const PUBLIC_TOOLS: readonly string[] = [
	"portents_roll",
	"portents_ask_roll",
	"portents_odds",
	"portents_map",
	"portents_verify_roll",
];
